const GRID_HEX: &[u8] = b"";

const GRID_VALUES: [u8; 8] = [1, 3, 5, 7, 9, 11, 13, 15];

fn hex_nibble(value: u8) -> u8 {
    match value {
        b'0'..=b'9' => value - b'0',
        b'a'..=b'f' => value - b'a' + 10,
        b'A'..=b'F' => value - b'A' + 10,
        _ => 0,
    }
}

fn grid_value(code: u16, lane: usize) -> u8 {
    let value_index = usize::from(code) * 4 + lane;
    let packed_index = value_index / 2;
    let high = hex_nibble(GRID_HEX[packed_index * 2]);
    let low = hex_nibble(GRID_HEX[packed_index * 2 + 1]);
    let packed = (high << 4) | low;
    GRID_VALUES[usize::from((packed >> ((value_index % 2) * 4)) & 0x07)]
}

pub(crate) fn dequantize_block(encoded: &[u8]) -> Vec<f32> {
    let scale = super::read_f16(encoded, 0);
    let low_codes = &encoded[2..66];
    let high_codes = &encoded[66..74];
    let signs = &encoded[74..106];
    let scales = &encoded[106..110];
    let mut output = Vec::with_capacity(256);
    for group in 0..8 {
        let scale_nibble = (scales[group / 2] >> ((group % 2) * 4)) & 0x0f;
        let group_scale = scale * (1.0 + 2.0 * f32::from(scale_nibble));
        for sub in 0..4 {
            for lane in 0..8 {
                let code_index = group * 8 + sub * 2 + lane / 4;
                let high_bit = (high_codes[code_index / 8] >> (code_index % 8)) & 1;
                let code = u16::from(low_codes[code_index]) | (u16::from(high_bit) << 8);
                let sign = if (signs[group * 4 + sub] >> lane) & 1 == 0 {
                    1.0
                } else {
                    -1.0
                };
                output.push(group_scale * f32::from(grid_value(code, lane % 4)) * sign);
            }
        }
    }
    output
}
